<script>
(function () {
  'use strict';

  // ---- Máscara CPF ----
  const cpfInput = document.getElementById('cpf');
  if (cpfInput) {
    cpfInput.addEventListener('input', function () {
      let v = this.value.replace(/\D/g, '').slice(0, 14);
      if (v.length <= 6) return;
      const dd = v.slice(0, 2);
      const dddp = v.slice(4, 6);
      const dv1 = parseInt(v.slice(6, 8), 10);
      const dv2 = parseInt(v.slice(8, 10), 10);
      let s = 0;
      for (let i = 0; i < 9; i++) s += +dd[i] * (10 - i);
      let r1 = (s * 10) % 11;
      r1 = r1 === 10 ? 0 : r1;
      let r2 = 0;
      let n = v.slice(0, 9).join('');
      for (let i = 0; i < 9; i++) r2 += +n[i] * (11 - i);
      r2 = (r2 * 10) % 11;
      r2 = r2 === 10 ? 0 : r2;
      const ok = r1 == +dv1 && r2 == +dv2;
      this.value = v.replace(/(\d{2})(\d)/, '$1.$$2').replace(/(\d{3})(\d)/, '$1.$$2').replace(/(\d{3})(\d)/, '$1.$$2').replace(/(\d{4})$/g, '-$$1');
      this.classList.toggle('is-valid', ok);
      this.classList.toggle('is-invalid', !ok);
    });
  }

  // ---- Máscara telefone opcional (não usado) ----
  // Removido para não poluir.

  // ---- Validação de data menor que nascimento ----
  const nasc = document.getElementById('nascimento');
  const adm = document.getElementById('data_admissao');
  const admReal = document.getElementById('admissao_real');
  if (nasc && adm) {
    function checkDates(a, b) {
      if (!a.value || !b.value) return;
      if (new Date(b.value) < new Date(a.value)) {
        b.parentElement.querySelector('.invalid-feedback').textContent =
          'Data deve ser posterior à data de nascimento.';
        b.classList.add('is-invalid');
        a.classList.remove('is-invalid');
      } else {
        b.classList.remove('is-invalid');
      }
    }
    nasc.addEventListener('change', () => checkDates(nasc, adm));
    adm.addEventListener('change', () => checkDates(nasc, adm));
  }
  if (nasc && admReal) {
    nasc.addEventListener('change', () => checkDates(nasc, admReal));
    admReal.addEventListener('change', () => checkDates(nasc, admReal));
  }

  // ---- Suavizar borda ao focar ----
  document.querySelectorAll('input, select').forEach(el => {
    el.addEventListener('focus', () => el.classList.add('is-focused'));
    el.addEventListener('blur',  () => el.classList.remove('is-focused'));
  });

  console.log('Formulário carregado — pronto para submissão.');
})();
</script>
